import type { ArchNode, NodeKind } from "./types";

// Short, plain-English explanations of what each component type actually
// does, plus a few real-world technologies that fill that role — so
// clicking a node teaches the "why", not just the "what it's labeled".
// Keyed by `${node_kind}:${type}`, mirroring the discriminated node types
// in backend/app/models/state.py. This is presentation-only reference
// content (never sent to or generated by the LLM) — safe to expand freely.
//
// `label` (added alongside the drag-and-drop component palette — see
// ComponentPalette.tsx) is this same catalog's single addition for that
// UI: a short, human title for the type ("Relational Database", not the
// raw "relational"), reusing this file as the one place a component
// type's name/description/examples all live rather than a second,
// parallel label table that could drift from this one.

export interface ComponentInfo {
  label: string;
  description: string;
  examples?: string[];
}

