/** Every addable (node_kind, type) pair for one kind, in the same order
 * declared above — used to build the component palette's tiles for a
 * given tab. Grouped/ordered here already, so no separate ordering table
 * to keep in sync. */
export function listComponentTypes(kind: NodeKind): { type: string; info: ComponentInfo }[] {
  const prefix = `${kind}:`;
  return Object.entries(INFO)
    .filter(([key]) => key.startsWith(prefix))
    .map(([key, info]) => ({ type: key.slice(prefix.length), info }));
}

const ROLE_NOTE: Record<string, string> = {
  cache: " Deployed here as a cache in front of the primary — absorbs read traffic so the primary doesn't take the full load.",
  replica: " Deployed here as a read replica of the primary — serves read traffic to improve throughput and availability.",
};

export function getComponentInfo(node: ArchNode): ComponentInfo | null {
  const base = INFO[`${node.node_kind}:${node.type}`];
  if (!base) return null;

  const role = typeof node.role === "string" ? node.role : undefined;
  if (node.node_kind === "database" && role && ROLE_NOTE[role]) {
    return { ...base, description: base.description + ROLE_NOTE[role] };
  }
  return base;
}
